    major = {v for v, n in freq.items() if v != bg and n >= 4}
    boxes = []
    for color in major:
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        boxes.append((color, min(r for r, c in cells),
                      max(r for r, c in cells), min(c for r, c in cells),
                      max(c for r, c in cells)))

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or v in major:
                continue
            # Small marker inside a major object's bounding box is noise
            # belonging to that object; otherwise remove it.
            inside = [b for b in boxes if b[1] <= r <= b[2]
                      and b[3] <= c <= b[4]]
            if inside:
                color = min(inside,
                            key=lambda b: abs((b[1] + b[2]) / 2 - r)
                                         + abs((b[3] + b[4]) / 2 - c))[0]
                out[r][c] = color
            else:
                out[r][c] = bg

